/**
 * Write the PowerSync sync rules from the sync spec: one bucket per business (every synced tenant
 * table of that business), one per organisation (its businesses and members), and one shared bucket for
 * the HSN master. The organisation comes from the token the API signs after checking membership.
 *
 *   pnpm --filter @gst/db exec tsx scripts/sync-rules.ts > ../../infra/powersync/sync-rules.yaml
 */
import { SYNC_TABLES, syncColumns } from '../src/sync/spec';

const cols = (t: string) => syncColumns(t).join(', ');
const lines: string[] = [
  '# GENERATED by packages/db/scripts/sync-rules.ts from packages/db/src/sync/spec.ts. Do not edit.',
  'bucket_definitions:',
];

// per business: every tenant table
lines.push('  by_business:');
lines.push(
  "    parameters: SELECT id AS business_id FROM businesses WHERE org_id = request.jwt() ->> 'org_id' AND deleted_at IS NULL",
);
lines.push('    data:');
for (const t of SYNC_TABLES.filter((x) => x.kind === 'tenant' || x.kind === 'tenant-lite'))
  lines.push(
    `      - SELECT ${cols(t.name)} FROM ${t.name} WHERE business_id = bucket.business_id`,
  );

// per organisation: the org-level tables
lines.push('  by_org:');
lines.push("    parameters: SELECT request.jwt() ->> 'org_id' AS org_id");
lines.push('    data:');
for (const t of SYNC_TABLES.filter((x) => x.kind === 'org'))
  lines.push(`      - SELECT ${cols(t.name)} FROM ${t.name} WHERE org_id = bucket.org_id`);

// shared reference data
lines.push('  reference:');
lines.push('    data:');
for (const t of SYNC_TABLES.filter((x) => x.kind === 'plain'))
  lines.push(`      - SELECT ${cols(t.name)} FROM ${t.name}`);

console.log(lines.join('\n'));
